CREATE FUNCTION public._notif_display_name(_uid uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(nullif(username,''), nullif(full_name,''), 'Someone')
  from public.profiles where id = _uid;
$$;


--
-- Name: _sync_banners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_banners() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.image_url is null and new.image is not null then new.image_url := new.image; end if;
  if new.image is null and new.image_url is not null then new.image := new.image_url; end if;
  if new.is_active is null and new.active is not null then new.is_active := new.active; end if;
  if new.active is null and new.is_active is not null then new.active := new.is_active; end if;
  return new;
end $$;


--
-- Name: _sync_coin_packages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_coin_packages() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.is_active is null and new.active is not null then new.is_active := new.active; end if;
  if new.active is null and new.is_active is not null then new.active := new.is_active; end if;
  if new.price is null and new.price_pkr is not null then new.price := new.price_pkr; end if;
  if new.price_pkr is null and new.price is not null then new.price_pkr := new.price; end if;
  return new;
end $$;


--
-- Name: _sync_gifts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_gifts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.emoji is null and new.icon is not null then new.emoji := new.icon; end if;
  if new.icon  is null and new.emoji is not null then new.icon  := new.emoji; end if;
  if new.price is null and new.price_coins is not null then new.price := new.price_coins; end if;
  if new.price_coins is null and new.price is not null then new.price_coins := new.price; end if;
  if new.is_active is null and new.active is not null then new.is_active := new.active; end if;
  if new.active is null and new.is_active is not null then new.active := new.is_active; end if;
  return new;
end $$;


--
-- Name: _sync_wallet_tx(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_wallet_tx() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.coins_delta is null and new.coins is not null then new.coins_delta := new.coins; end if;
  if new.coins is null and new.coins_delta is not null then new.coins := new.coins_delta; end if;
  if new.diamonds_delta is null and new.diamonds is not null then new.diamonds_delta := new.diamonds; end if;
  if new.diamonds is null and new.diamonds_delta is not null then new.diamonds := new.diamonds_delta; end if;
  return new;
end $$;


--
-- Name: accept_seat_invite(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_seat_invite(_invite_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  inv record;
  target_seat int;
  seat_max int;
  i int;
begin
  if me is null then raise exception 'not authenticated'; end if;

  select * into inv from public.seat_invites where id = _invite_id;
  if not found then raise exception 'invite not found'; end if;
  if inv.to_user <> me then raise exception 'not your invite'; end if;
  if inv.status <> 'pending' then raise exception 'invite already responded'; end if;

  -- Pick seat: explicit or first free (skip seat 0 = host)
  if inv.seat_index is not null then
    target_seat := inv.seat_index;
  else
    select seat_count into seat_max from public.live_rooms where id = inv.room_id;
    target_seat := null;
    for i in 1 .. coalesce(seat_max, 8) - 1 loop
      if not exists (
        select 1 from public.room_members
        where room_id = inv.room_id and seat_index = i
      ) then
        target_seat := i;
        exit;
      end if;
    end loop;
    if target_seat is null then raise exception 'no free seat'; end if;
  end if;

  update public.seat_invites
    set status = 'accepted', responded_at = now()
    where id = _invite_id;

  insert into public.room_members (room_id, user_id, seat_index)
    values (inv.room_id, me, target_seat)
    on conflict (room_id, user_id) do update
      set seat_index = excluded.seat_index;

  return target_seat;
end $$;


--
-- Name: accept_video_swap_invite(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_video_swap_invite(_invite_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  inv record;
  r_host uuid;
  my_seat int;
begin
  if me is null then raise exception 'not authenticated'; end if;

  select * into inv from public.seat_invites where id = _invite_id;
  if not found then raise exception 'invite not found'; end if;
  if inv.to_user <> me then raise exception 'not your invite'; end if;
  if inv.status <> 'pending' then raise exception 'invite already responded'; end if;
  if coalesce(inv.seat_index, -1) <> 0 then
    raise exception 'not a video swap invite';
  end if;

  select host_id into r_host from public.live_rooms where id = inv.room_id;
  if r_host is null then raise exception 'room not found'; end if;
  if inv.from_user <> r_host then raise exception 'only host can send video swap'; end if;

  -- Find my current seat (must be on some audio seat > 0)
  select seat_index into my_seat
    from public.room_members
   where room_id = inv.room_id and user_id = me;
  if my_seat is null or my_seat = 0 then
    raise exception 'you must be on an audio seat to accept';
  end if;

  update public.seat_invites
    set status = 'accepted', responded_at = now()
   where id = _invite_id;

  -- Atomic swap: temp free both, then place.
  update public.room_members set seat_index = null
   where room_id = inv.room_id and user_id in (me, r_host);

  insert into public.room_members (room_id, user_id, seat_index)
    values (inv.room_id, me, 0)
    on conflict (room_id, user_id) do update set seat_index = 0;

  insert into public.room_members (room_id, user_id, seat_index)
    values (inv.room_id, r_host, my_seat)
    on conflict (room_id, user_id) do update set seat_index = my_seat;

  return my_seat;
end $$;


--
-- Name: adjust_coins(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_coins(_user_id uuid, _delta bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  new_balance bigint;
begin
  if me is null then raise exception 'not authenticated'; end if;
  if not public.is_admin(me) then raise exception 'admin only'; end if;

  update public.profiles
     set coins = greatest(0, coalesce(coins, 0) + _delta)
   where id = _user_id
   returning coins into new_balance;

  if not found then raise exception 'user not found'; end if;

  insert into public.admin_logs (admin_id, action, target, details)
    values (me, 'adjust_coins', _user_id::text,
            jsonb_build_object('delta', _delta, 'new_balance', new_balance));

  return new_balance;
end $$;


--
-- Name: admin_set_free_account(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_free_account(_user_id uuid, _value boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Only admins can change free accounts'; END IF;
  UPDATE public.profiles SET is_free = _value, updated_at = now() WHERE id = _user_id;
END; $$;


--
-- Name: admin_update_user(uuid, integer, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user(_user_id uuid, _level integer, _coins bigint, _is_vip boolean, _status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can update users';
  END IF;
  UPDATE public.profiles
    SET level = GREATEST(0, _level),
        coins = GREATEST(0, _coins),
        is_vip = _is_vip,
        vip_expiry = CASE
          WHEN _is_vip AND (vip_expiry IS NULL OR vip_expiry < now())
            THEN now() + interval '30 days'
          WHEN NOT _is_vip THEN NULL
          ELSE vip_expiry END,
        status = _status,
        updated_at = now()
    WHERE id = _user_id;
END;
$$;


