CREATE TABLE public.custom_themes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    image_url text NOT NULL,
    coins_paid integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    admin_notes text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT custom_themes_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text])))
);


--
-- Name: approve_custom_theme(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_custom_theme(_id uuid) RETURNS public.custom_themes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  row public.custom_themes;
  dur_h int;
begin
  if not public.is_admin(me) then raise exception 'admin only'; end if;
  select custom_theme_duration_hours into dur_h from public.app_settings where id = 'global';

  update public.custom_themes
     set status = 'approved',
         reviewed_by = me,
         reviewed_at = now(),
         approved_at = now(),
         expires_at = now() + (coalesce(dur_h, 24) || ' hours')::interval
   where id = _id and status = 'pending'
   returning * into row;
  if row.id is null then raise exception 'request not found or already reviewed'; end if;

  insert into public.notifications
    (user_id, kind, title, body, data, actor_id, entity_type, entity_id)
  values
    (row.user_id, 'account_action',
     'Custom theme approved',
     'Your uploaded theme is live for ' || coalesce(dur_h, 24) || ' hours',
     jsonb_build_object('custom_theme_id', row.id, 'expires_at', row.expires_at),
     me, 'custom_theme', row.id::text);

  return row;
end $$;


--
-- Name: approve_recharge(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_recharge(_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _req public.recharge_requests%ROWTYPE;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only admins can approve recharges';
  END IF;

  SELECT * INTO _req FROM public.recharge_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Recharge request not found';
  END IF;
  IF _req.status <> 'pending' THEN
    RAISE EXCEPTION 'Recharge request already processed';
  END IF;

  UPDATE public.recharge_requests
    SET status = 'approved', processed_at = now()
    WHERE id = _request_id;

  UPDATE public.profiles
    SET coins = coins + _req.coins, updated_at = now()
    WHERE id = _req.user_id;

  INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
    VALUES (_req.user_id, 'recharge', _req.coins, 'Recharge approved');
END;
$$;


--
-- Name: approve_recharge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_recharge(_request_id uuid, _admin_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _req public.recharge_requests%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can approve recharges';
  end if;

  select * into _req from public.recharge_requests where id = _request_id for update;
  if not found then
    raise exception 'Recharge request not found';
  end if;
  if _req.status <> 'pending' then
    raise exception 'Recharge request already processed';
  end if;

  update public.recharge_requests
    set status = 'approved',
        processed_at = now(),
        admin_note = coalesce(_admin_note, admin_note)
    where id = _request_id;

  update public.profiles
    set coins = coins + _req.coins,
        updated_at = now()
    where id = _req.user_id;

  insert into public.wallet_transactions (user_id, kind, coins, note)
    values (_req.user_id, 'recharge', _req.coins, coalesce(_admin_note, 'Recharge approved'));
end;
$$;


--
-- Name: approve_withdrawal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_withdrawal(_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Only admins can approve withdrawals'; END IF;
  UPDATE public.withdrawal_requests SET status = 'approved', processed_at = now()
    WHERE id = _request_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Withdrawal not found or already processed'; END IF;
END;
$$;


--
-- Name: are_friends(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.are_friends(_a uuid, _b uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.friendships
    where status = 'accepted'
      and ((requester_id = _a and addressee_id = _b)
        or (requester_id = _b and addressee_id = _a))
  );
$$;


--
-- Name: award_milestone_gift(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_milestone_gift(_room_id uuid, _receiver_id uuid, _gift_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller uuid := auth.uid();
  host uuid;
  coin_total bigint;
  g record;
  event_id uuid;
begin
  if caller is null then
    raise exception 'auth required';
  end if;

  select host_id into host from public.live_rooms where id = _room_id;
  if host is null then
    raise exception 'room not found';
  end if;
  if host <> caller then
    raise exception 'only host can award milestone';
  end if;

  if exists (select 1 from public.live_rooms where id = _room_id and milestone_awarded_at is not null) then
    raise exception 'milestone already awarded for this room';
  end if;

  select coalesce(sum(coins_spent), 0)::bigint into coin_total
  from public.gift_sends where room_id = _room_id;

  if coin_total < 300000 then
    raise exception 'room not yet ranked (need 300k coins)';
  end if;

  select id, name, coalesce(emoji, icon, '🎁') as emoji into g
  from public.gifts
  where id = _gift_id
    and is_milestone = true
    and coalesce(is_active, active, true) = true
  limit 1;

  if g.id is null then
    raise exception 'selected gift is not an active milestone gift';
  end if;

  insert into public.gift_events (room_id, sender_id, sender_name, gift_id, gift_emoji, gift_name, coins)
  select _room_id, host, coalesce(hp.username, 'Host'), g.id, g.emoji, g.name, 0
  from public.profiles hp where hp.id = host
  returning id into event_id;

  update public.live_rooms
    set milestone_awarded_at = now(),
        milestone_receiver_id = _receiver_id,
        milestone_gift_id = g.id
    where id = _room_id;

  return event_id;
end;
$$;


--
-- Name: consume_agora_slot(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_agora_slot(_kind text, _minutes numeric) RETURNS TABLE(app_id text, app_certificate text, slot_index integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s public.agora_slots%ROWTYPE;
BEGIN
  SELECT * INTO s
    FROM public.agora_slots
   WHERE kind = _kind
     AND is_active = true
     AND minutes_used + COALESCE(_minutes, 0) <= minutes_quota
   ORDER BY slot_index ASC
   FOR UPDATE SKIP LOCKED
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  UPDATE public.agora_slots
     SET minutes_used  = minutes_used + COALESCE(_minutes, 0),
         last_used_at  = now(),
         updated_at    = now(),
         is_active     = CASE WHEN minutes_used + COALESCE(_minutes, 0) >= minutes_quota THEN false ELSE true END,
         exhausted_at  = CASE WHEN minutes_used + COALESCE(_minutes, 0) >= minutes_quota AND exhausted_at IS NULL THEN now() ELSE exhausted_at END
   WHERE id = s.id;

  app_id := s.app_id;
  app_certificate := s.app_certificate;
  slot_index := s.slot_index;
  RETURN NEXT;
END;
$$;


--
-- Name: enforce_gallery_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_gallery_limits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _pub INT; _priv INT;
BEGIN
  SELECT count(*) FILTER (WHERE is_public),
         count(*) FILTER (WHERE NOT is_public)
    INTO _pub, _priv
    FROM public.gallery_images
    WHERE user_id = NEW.user_id AND id <> NEW.id;
  IF NEW.is_public AND _pub >= 5 THEN
    RAISE EXCEPTION 'You can only have 5 public photos';
  END IF;
  IF NOT NEW.is_public AND _priv >= 5 THEN
    RAISE EXCEPTION 'You can only have 5 private photos';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ensure_host_family(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_host_family(_host_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  fid uuid;
  host_name text;
begin
  select id into fid from public.families where owner_id = _host_id;
  if fid is not null then
    return fid;
  end if;

  select coalesce(username, 'Host') into host_name
  from public.profiles where id = _host_id;

  insert into public.families(owner_id, name, badge)
  values (_host_id, host_name || '''s Family', '👑')
  returning id into fid;

  insert into public.family_members(family_id, user_id, role)
  values (fid, _host_id, 'owner')
  on conflict do nothing;

  return fid;
end;
$$;


--
-- Name: ensure_room_host_participant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_room_host_participant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _username text;
  _avatar text;
BEGIN
  SELECT username, avatar INTO _username, _avatar
    FROM public.profiles
    WHERE id = NEW.host_id;

  INSERT INTO public.room_participants (
    room_id,
    user_id,
    username,
    avatar,
    seat_status
  )
  VALUES (
    NEW.id,
    NEW.host_id,
    COALESCE(_username, 'Host'),
    _avatar,
    'speaker'
  )
  ON CONFLICT (room_id, user_id)
  DO UPDATE SET
    username = EXCLUDED.username,
    avatar = EXCLUDED.avatar,
    seat_status = 'speaker',
    updated_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: equip_frame(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equip_frame(_frame_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _expiry timestamptz;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in'; END IF;
  IF _frame_id IS NULL THEN
    UPDATE public.profiles SET frame = NULL, frame_expires_at = NULL, updated_at = now() WHERE id = _uid;
    RETURN;
  END IF;
  SELECT expires_at INTO _expiry FROM public.user_frames
    WHERE user_id = _uid AND frame_id = _frame_id;
  IF NOT FOUND OR _expiry <= now() THEN
    RAISE EXCEPTION 'You do not own this frame or it has expired';
  END IF;
  UPDATE public.profiles
    SET frame = _frame_id::text, frame_expires_at = _expiry, updated_at = now()
    WHERE id = _uid;
END;
$$;


--
-- Name: equip_theme(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.equip_theme(_theme_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _is_free BOOLEAN;
  _owns BOOLEAN;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in'; END IF;
  IF _theme_id IS NULL THEN
    UPDATE public.profiles SET theme_id = NULL, updated_at = now() WHERE id = _uid;
    RETURN;
  END IF;
  SELECT is_free INTO _is_free FROM public.themes WHERE id = _theme_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Theme not found'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.user_themes WHERE user_id = _uid AND theme_id = _theme_id)
    INTO _owns;
  IF NOT _is_free AND NOT _owns THEN
    RAISE EXCEPTION 'You do not own this theme';
  END IF;
  UPDATE public.profiles SET theme_id = _theme_id, updated_at = now() WHERE id = _uid;
END;
$$;


--
-- Name: finalize_room_gifts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_room_gifts(_room_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  IF _room_id IS NULL THEN RETURN; END IF;

  FOR r IN
    SELECT receiver_id, SUM(diamonds_earned)::bigint AS total_diamonds
      FROM public.gift_sends
     WHERE room_id = _room_id
       AND finalized_at IS NULL
       AND receiver_id IS NOT NULL
     GROUP BY receiver_id
  LOOP
    IF r.total_diamonds > 0 THEN
      UPDATE public.profiles
         SET diamonds = diamonds + r.total_diamonds
       WHERE id = r.receiver_id;

      INSERT INTO public.wallet_transactions
        (user_id, kind, diamonds_delta, ref_type, ref_id, note)
      VALUES
        (r.receiver_id, 'gift_received', r.total_diamonds, 'room_gift', _room_id,
         'Room gifts finalized');
    END IF;
  END LOOP;

  UPDATE public.gift_sends
     SET finalized_at = now()
   WHERE room_id = _room_id
     AND finalized_at IS NULL;
END;
$$;


--
-- Name: gallery_object_visible(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gallery_object_visible(_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.gallery_images gi
    WHERE gi.path = _path
      AND (
        gi.is_public
        OR gi.user_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM public.gallery_unlocks gu
          WHERE gu.owner_id = gi.user_id
            AND gu.viewer_id = auth.uid()
            AND gu.status = 'accepted'
        )
      )
  )
$$;


--
-- Name: gen_user_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_user_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  candidate text;
  exists_already boolean;
begin
  loop
    candidate := lpad((floor(random() * 900000) + 100000)::int::text, 6, '0');
    select exists (select 1 from public.profiles where user_code = candidate) into exists_already;
    exit when not exists_already;
  end loop;
  return candidate;
end;
$$;


