--
-- Name: guard_room_participant_insert_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_room_participant_insert_defaults() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _host uuid;
BEGIN
  SELECT host_id INTO _host FROM public.rooms WHERE id = NEW.room_id;

  IF NEW.user_id = _host THEN
    NEW.seat_status := 'speaker';
  ELSE
    NEW.seat_status := 'viewer';
    NEW.is_moderator := false;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_room_participant_protected_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_room_participant_protected_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _actor uuid := auth.uid();
  _host uuid;
  _actor_is_mod boolean := false;
BEGIN
  IF current_user IN ('postgres', 'service_role') THEN
    RETURN NEW;
  END IF;

  IF _actor IS NULL THEN
    RAISE EXCEPTION 'Sign in first';
  END IF;

  SELECT host_id INTO _host FROM public.rooms WHERE id = NEW.room_id;
  SELECT COALESCE(is_moderator, false) INTO _actor_is_mod
    FROM public.room_participants
    WHERE room_id = NEW.room_id AND user_id = _actor;

  IF _actor = _host OR COALESCE(_actor_is_mod, false) THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id <> _actor THEN
    RAISE EXCEPTION 'You can only update your own room presence';
  END IF;

  IF NEW.is_moderator IS DISTINCT FROM OLD.is_moderator
     OR NEW.points IS DISTINCT FROM OLD.points
     OR NEW.seat_status IS DISTINCT FROM OLD.seat_status THEN
    RAISE EXCEPTION 'Only the host or a moderator can change stage permissions';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  base_username text;
  candidate_username text;
  suffix int := 0;
begin
  base_username := split_part(coalesce(new.email, 'user'), '@', 1);
  candidate_username := base_username;

  while exists (select 1 from public.profiles where username = candidate_username) loop
    suffix := suffix + 1;
    candidate_username := base_username || suffix::text;
  end loop;

  insert into public.profiles (id, username, full_name, avatar, user_code)
  values (
    new.id,
    candidate_username,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url',
    public.gen_user_code()
  )
  on conflict (id) do nothing;

  insert into public.user_roles (user_id, role)
  values (new.id, 'user')
  on conflict (user_id, role) do nothing;

  return new;
end;
$$;


