--
-- Name: leaderboard(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leaderboard(_kind text, _period text) RETURNS TABLE(user_id uuid, username text, avatar text, points bigint, is_vip boolean, level integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH span AS (
    SELECT CASE _period
      WHEN 'weekly' THEN now() - interval '7 days'
      WHEN 'monthly' THEN now() - interval '30 days'
      ELSE '-infinity'::timestamptz
    END AS since
  ),
  agg AS (
    SELECT
      CASE WHEN _kind = 'gifters' THEN ge.sender_id ELSE r.host_id END AS uid,
      SUM(ge.coins)::bigint AS pts
    FROM public.gift_events ge
    LEFT JOIN public.rooms r ON r.id = ge.room_id
    CROSS JOIN span
    WHERE ge.created_at >= span.since
    GROUP BY 1
  )
  SELECT a.uid, p.username, p.avatar, a.pts, p.is_vip, p.level
  FROM agg a
  JOIN public.profiles p ON p.id = a.uid
  WHERE a.uid IS NOT NULL AND a.pts > 0
  ORDER BY a.pts DESC
  LIMIT 30;
$$;


--
-- Name: like_room_seat(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.like_room_seat(_room_id uuid, _seat_index integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  liker uuid := auth.uid();
  total int;
begin
  if liker is null then
    raise exception 'auth required';
  end if;

  insert into public.room_seat_likes(room_id, seat_index, liker_id)
  values (_room_id, _seat_index, liker);

  select count(*) into total
  from public.room_seat_likes
  where room_id = _room_id and seat_index = _seat_index;

  return total;
end;
$$;


--
-- Name: ludo_payout(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ludo_payout(_bet integer, _players integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _coins integer;
  _pot integer;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Sign in';
  END IF;

  _pot := GREATEST(_bet, 0) * GREATEST(_players, 1);

  UPDATE public.profiles
    SET coins = coins + _pot, updated_at = now()
    WHERE id = _uid
    RETURNING coins INTO _coins;

  INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
    VALUES (_uid, 'ludo_win', _pot, 'Ludo winnings');

  RETURN _coins;
END;
$$;


--
-- Name: ludo_place_bet(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ludo_place_bet(_room_id uuid, _bet integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _coins integer;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to play';
  END IF;
  IF _bet < 1 THEN
    RAISE EXCEPTION 'Invalid bet';
  END IF;

  UPDATE public.profiles
    SET coins = coins - _bet, updated_at = now()
    WHERE id = _uid AND coins >= _bet
    RETURNING coins INTO _coins;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Not enough coins';
  END IF;

  INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
    VALUES (_uid, 'ludo_bet', -_bet, 'Ludo bet');

  RETURN _coins;
END;
$$;


