  where user_id = auth.uid() and read_at is null;
$$;


--
-- Name: notify_user(uuid, public.notification_kind, text, text, jsonb, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_user(_user_id uuid, _kind public.notification_kind, _title text, _body text DEFAULT NULL::text, _data jsonb DEFAULT '{}'::jsonb, _actor uuid DEFAULT NULL::uuid, _entity_type text DEFAULT NULL::text, _entity_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _id uuid;
begin
  if _user_id is null then return null; end if;
  -- Skip only if the user has explicitly set this kind to false.
  if exists (
    select 1 from public.notification_prefs
    where user_id = _user_id and (in_app -> _kind::text)::boolean = false
  ) then
    return null;
  end if;
  insert into public.notifications(user_id, kind, title, body, data, actor_id, entity_type, entity_id)
  values (_user_id, _kind, _title, _body, coalesce(_data,'{}'::jsonb), _actor, _entity_type, _entity_id)
  returning id into _id;
  begin
    perform pg_notify('notif_push', json_build_object(
      'id', _id, 'user_id', _user_id, 'kind', _kind,
      'title', _title, 'body', _body, 'data', _data
    )::text);
  exception when others then
    -- ignore pg_notify failures
    null;
  end;
  return _id;
exception when others then
  raise warning 'notify_user skipped: %', SQLERRM;
  return null;
end $$;


--
-- Name: partner_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pct numeric;
  _active boolean;
  _result jsonb;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in'; END IF;
  SELECT percentage, is_active INTO _pct, _active FROM public.partners WHERE user_id = _uid;
  IF _pct IS NULL THEN RAISE EXCEPTION 'You are not a partner'; END IF;

  WITH approved AS (
    SELECT r.amount_paid, r.coins, COALESCE(r.processed_at, r.created_at) AS at
    FROM public.recharge_requests r
    JOIN public.profiles p ON p.id = r.user_id
    WHERE r.status = 'approved' AND COALESCE(p.is_free, false) = false
  ),
  totals AS (SELECT COALESCE(SUM(amount_paid),0) rev, COALESCE(SUM(coins),0) coins FROM approved),
  today AS (SELECT COALESCE(SUM(amount_paid),0) rev, COALESCE(SUM(coins),0) coins FROM approved WHERE at >= date_trunc('day', now())),
  daily AS (
    SELECT to_char(date_trunc('day', at), 'YYYY-MM-DD') AS d,
           COALESCE(SUM(amount_paid),0) rev, COALESCE(SUM(coins),0) coins
    FROM approved WHERE at >= now() - interval '7 days'
    GROUP BY 1 ORDER BY 1 DESC
  )
  SELECT jsonb_build_object(
    'percentage', _pct,
    'is_active', COALESCE(_active, false),
    'total_revenue', (SELECT rev FROM totals),
    'total_coins', (SELECT coins FROM totals),
    'total_profit', round((SELECT rev FROM totals) * _pct / 100.0, 2),
    'today_revenue', (SELECT rev FROM today),
    'today_coins', (SELECT coins FROM today),
    'today_profit', round((SELECT rev FROM today) * _pct / 100.0, 2),
    'daily', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'day', d, 'revenue', rev, 'coins', coins,
        'profit', round(rev * _pct / 100.0, 2))) FROM daily), '[]'::jsonb)
  ) INTO _result;
  RETURN _result;
END; $$;


--
-- Name: pk_matches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pk_matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_a uuid NOT NULL,
    host_b uuid NOT NULL,
    room_a uuid NOT NULL,
    room_b uuid NOT NULL,
    duration_sec integer NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    score_a bigint DEFAULT 0 NOT NULL,
    score_b bigint DEFAULT 0 NOT NULL,
    winner_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pk_matches_status_check CHECK ((status = ANY (ARRAY['active'::text, 'ended'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.pk_matches REPLICA IDENTITY FULL;


--
-- Name: pk_end_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_end_match(_match_id uuid) RETURNS public.pk_matches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  m public.pk_matches;
  s record;
  win uuid;
begin
  select * into m from public.pk_matches where id = _match_id for update;
  if m.id is null then raise exception 'match not found'; end if;
  if m.status <> 'active' then return m; end if;

  -- Only participants, admins, or auto-close after end can finalize
  if me is not null and me <> m.host_a and me <> m.host_b then
    if not public.has_role(me, 'admin'::app_role) then
      raise exception 'not a participant';
    end if;
  end if;

  select score_a, score_b into s from public.pk_match_score(m.id);
  win := case
    when s.score_a > s.score_b then m.host_a
    when s.score_b > s.score_a then m.host_b
    else null
  end;

  update public.pk_matches
     set status = 'ended', ended_at = now(),
         score_a = s.score_a, score_b = s.score_b,
         winner_id = win
   where id = m.id
  returning * into m;

  update public.live_rooms set active_pk_match_id = null
   where id in (m.room_a, m.room_b) and active_pk_match_id = m.id;

  -- history rows for both hosts (best-effort)
  insert into public.pk_battles(host_id, room_id, room_title, my_score, opponent_name, opponent_score, result, started_at, ended_at)
  select m.host_a, m.room_a,
         coalesce((select title from public.live_rooms where id = m.room_a), 'PK Battle'),
         s.score_a,
         coalesce((select username from public.profiles where id = m.host_b), 'Opponent'),
         s.score_b,
         case when win = m.host_a then 'win' when win = m.host_b then 'lose' else 'draw' end,
         m.started_at, now();

  insert into public.pk_battles(host_id, room_id, room_title, my_score, opponent_name, opponent_score, result, started_at, ended_at)
  select m.host_b, m.room_b,
         coalesce((select title from public.live_rooms where id = m.room_b), 'PK Battle'),
         s.score_b,
         coalesce((select username from public.profiles where id = m.host_a), 'Opponent'),
         s.score_a,
         case when win = m.host_b then 'win' when win = m.host_a then 'lose' else 'draw' end,
         m.started_at, now();

  return m;
end;
$$;


--
-- Name: pk_join_random_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_join_random_queue(_duration_sec integer) RETURNS public.pk_matches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  my_room public.live_rooms;
  opp record;
  opp_room public.live_rooms;
  m public.pk_matches;
begin
  if me is null then raise exception 'auth required'; end if;
  if _duration_sec not in (180, 300, 600) then raise exception 'invalid duration'; end if;

  select * into my_room from public.live_rooms
    where host_id = me and status = 'live'
    order by created_at desc limit 1;
  if my_room.id is null then raise exception 'you must be live to matchmake'; end if;
  if my_room.active_pk_match_id is not null then raise exception 'already in a PK match'; end if;

  -- Try to grab an opponent: oldest queued host with same duration whose room is still live & free.
  select q.host_id, q.room_id
    into opp
    from public.pk_match_queue q
    join public.live_rooms lr on lr.id = q.room_id
   where q.host_id <> me
     and q.duration_sec = _duration_sec
     and lr.status = 'live'
     and lr.active_pk_match_id is null
   order by q.created_at asc
   for update skip locked
   limit 1;

  if opp.host_id is not null then
    -- pair them: remove both queue entries, create match, flag both rooms
    delete from public.pk_match_queue where host_id in (me, opp.host_id);

    select * into opp_room from public.live_rooms where id = opp.room_id;

    insert into public.pk_matches(host_a, host_b, room_a, room_b, duration_sec, ends_at)
    values (opp.host_id, me, opp_room.id, my_room.id, _duration_sec, now() + make_interval(secs => _duration_sec))
    returning * into m;

    update public.live_rooms set active_pk_match_id = m.id where id in (m.room_a, m.room_b);
    return m;
  end if;

  -- No opponent yet — enqueue self (upsert to allow duration change).
  insert into public.pk_match_queue(host_id, room_id, duration_sec)
  values (me, my_room.id, _duration_sec)
  on conflict (host_id) do update
     set room_id = excluded.room_id,
         duration_sec = excluded.duration_sec,
         created_at = now();

  return null;
end;
$$;


--
-- Name: pk_leave_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_leave_queue() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from public.pk_match_queue where host_id = auth.uid();
$$;


--
-- Name: pk_match_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_match_score(_match_id uuid) RETURNS TABLE(score_a bigint, score_b bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with m as (select * from public.pk_matches where id = _match_id)
  select
    coalesce(sum(case when gs.receiver_id = m.host_a then gs.coins_spent end), 0)::bigint as score_a,
    coalesce(sum(case when gs.receiver_id = m.host_b then gs.coins_spent end), 0)::bigint as score_b
  from m
  left join public.gift_sends gs
    on gs.receiver_id in (m.host_a, m.host_b)
   and gs.created_at >= m.started_at
   and gs.created_at <= coalesce(m.ended_at, m.ends_at);
$$;


--
-- Name: pk_respond_invite(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_respond_invite(_invite_id uuid, _accept boolean) RETURNS public.pk_matches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  inv public.pk_invites;
  m public.pk_matches;
  my_room public.live_rooms;
begin
  if me is null then raise exception 'auth required'; end if;

  select * into inv from public.pk_invites where id = _invite_id for update;
  if inv.id is null then raise exception 'invite not found'; end if;
  if inv.to_host <> me then raise exception 'not your invite'; end if;
  if inv.status <> 'pending' then raise exception 'invite already handled'; end if;
  if inv.expires_at < now() then
    update public.pk_invites set status = 'expired' where id = inv.id;
    raise exception 'invite expired';
  end if;

  if not _accept then
    update public.pk_invites set status = 'declined', responded_at = now() where id = inv.id;
    return null;
  end if;

  -- my (accepting host) current live room
  select * into my_room from public.live_rooms
    where host_id = me and status = 'live'
    order by created_at desc limit 1;
  if my_room.id is null then raise exception 'you must be live to accept'; end if;
  if my_room.active_pk_match_id is not null then raise exception 'you are already in a PK'; end if;

  insert into public.pk_matches(host_a, host_b, room_a, room_b, duration_sec, ends_at)
  values (inv.from_host, me, inv.from_room, my_room.id, inv.duration_sec, now() + make_interval(secs => inv.duration_sec))
  returning * into m;

  update public.live_rooms set active_pk_match_id = m.id where id in (m.room_a, m.room_b);
  update public.pk_invites set status = 'accepted', responded_at = now(), match_id = m.id where id = inv.id;

  return m;
end;
$$;


--
-- Name: pk_invites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pk_invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    from_host uuid NOT NULL,
    to_host uuid NOT NULL,
    from_room uuid NOT NULL,
    to_room uuid,
    duration_sec integer DEFAULT 180 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    match_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    responded_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '00:00:45'::interval) NOT NULL,
    CONSTRAINT pk_invites_duration_sec_check CHECK ((duration_sec = ANY (ARRAY[180, 300, 600]))),
    CONSTRAINT pk_invites_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text, 'expired'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.pk_invites REPLICA IDENTITY FULL;


--
-- Name: pk_send_invite(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pk_send_invite(_to_host uuid, _duration_sec integer) RETURNS public.pk_invites
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  my_room public.live_rooms;
  their_room public.live_rooms;
  inv public.pk_invites;
begin
  if me is null then raise exception 'auth required'; end if;
  if me = _to_host then raise exception 'cannot challenge yourself'; end if;
  if _duration_sec not in (180, 300, 600) then raise exception 'invalid duration'; end if;

  select * into my_room from public.live_rooms
    where host_id = me and status = 'live'
    order by created_at desc limit 1;
  if my_room.id is null then raise exception 'you must be live to challenge'; end if;
  if my_room.active_pk_match_id is not null then raise exception 'already in a PK match'; end if;

  select * into their_room from public.live_rooms
    where host_id = _to_host and status = 'live'
    order by created_at desc limit 1;
  if their_room.id is null then raise exception 'opponent is not live'; end if;
  if their_room.active_pk_match_id is not null then raise exception 'opponent already in a PK'; end if;

  -- expire any old pendings between these two
  update public.pk_invites
     set status = 'expired'
   where status = 'pending'
     and ((from_host = me and to_host = _to_host)
       or (from_host = _to_host and to_host = me));

  insert into public.pk_invites(from_host, to_host, from_room, to_room, duration_sec)
  values (me, _to_host, my_room.id, their_room.id, _duration_sec)
  returning * into inv;

  return inv;
end;
$$;


--
-- Name: game_rounds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.game_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    game_id uuid NOT NULL,
    user_id uuid NOT NULL,
    bet_coins integer NOT NULL,
    outcome text NOT NULL,
    multiplier numeric(6,2) DEFAULT 0 NOT NULL,
    payout_coins integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT game_rounds_bet_coins_check CHECK ((bet_coins > 0))
);


--
-- Name: play_lucky_spin(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.play_lucky_spin(_bet integer) RETURNS public.game_rounds
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  sender uuid := auth.uid();
  g public.games;
  new_balance int;
  roll int;
  mult numeric(6,2);
  outc text;
  payout int;
  round_row public.game_rounds;
begin
  if sender is null then raise exception 'not authenticated'; end if;
  select * into g from public.games where slug = 'lucky_spin' and active;
  if not found then raise exception 'game not available'; end if;
  if _bet < g.min_bet or _bet > g.max_bet then
    raise exception 'bet out of range (% - %)', g.min_bet, g.max_bet;
  end if;

  -- Deduct bet
  update public.profiles
     set coins = coins - _bet
   where id = sender and coins >= _bet
   returning coins into new_balance;
  if not found then raise exception 'insufficient coins'; end if;

  -- Weighted roll 1..100
  roll := floor(random() * 100) + 1;
  if roll <= 55 then       outc := 'lose'; mult := 0;
  elsif roll <= 80 then    outc := '1.5x'; mult := 1.5;
  elsif roll <= 93 then    outc := '2x';   mult := 2;
  elsif roll <= 99 then    outc := '5x';   mult := 5;
  else                     outc := '10x';  mult := 10;
  end if;

  payout := floor(_bet * mult);

  if payout > 0 then
    update public.profiles set coins = coins + payout
     where id = sender returning coins into new_balance;
  end if;

  insert into public.game_rounds (game_id, user_id, bet_coins, outcome, multiplier, payout_coins)
  values (g.id, sender, _bet, outc, mult, payout)
  returning * into round_row;

  insert into public.wallet_transactions
    (user_id, kind, coins_delta, balance_coins_after, ref_type, ref_id, note)
  values
    (sender, 'game', payout - _bet, new_balance, 'game', round_row.id,
     'Lucky Spin: ' || outc);

  return round_row;
end $$;


--
-- Name: purchase_frame(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_frame(_frame_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _frame public.dp_frames%ROWTYPE;
  _base timestamptz;
  _expiry timestamptz;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to buy frames'; END IF;
  SELECT * INTO _frame FROM public.dp_frames WHERE id = _frame_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Frame not found'; END IF;

  IF _frame.price > 0 THEN
    UPDATE public.profiles SET coins = coins - _frame.price, updated_at = now()
      WHERE id = _uid AND coins >= _frame.price;
    IF NOT FOUND THEN RAISE EXCEPTION 'Not enough coins'; END IF;
    INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
      VALUES (_uid, 'frame', -_frame.price, 'Bought frame ' || _frame.name);
  END IF;

  -- extend from current expiry if still active
  SELECT GREATEST(now(), COALESCE(expires_at, now())) INTO _base
    FROM public.user_frames WHERE user_id = _uid AND frame_id = _frame_id;
  IF _base IS NULL THEN _base := now(); END IF;
  _expiry := _base + (_frame.duration_days || ' days')::interval;

  INSERT INTO public.user_frames (user_id, frame_id, expires_at)
    VALUES (_uid, _frame_id, _expiry)
    ON CONFLICT (user_id, frame_id)
    DO UPDATE SET expires_at = _expiry;

  UPDATE public.profiles
    SET frame = _frame_id::text, frame_expires_at = _expiry, updated_at = now()
    WHERE id = _uid;
END;
$$;


--
-- Name: user_themes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_themes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    theme_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    purchased_price_diamonds integer DEFAULT 0 NOT NULL
);


--
-- Name: purchase_shop_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_shop_item(_theme_id uuid) RETURNS public.user_themes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _t public.themes%rowtype;
  _new_bal int;
  _expires timestamptz;
  _row public.user_themes;
begin
  if _uid is null then raise exception 'Sign in to buy'; end if;
  select * into _t from public.themes where id = _theme_id and is_active;
  if not found then raise exception 'Item not found'; end if;
  if _t.price_diamonds < 0 then raise exception 'Invalid price'; end if;

  if _t.price_diamonds > 0 then
    update public.profiles
       set diamonds = diamonds - _t.price_diamonds, updated_at = now()
     where id = _uid and diamonds >= _t.price_diamonds
     returning diamonds into _new_bal;
    if not found then raise exception 'Not enough diamonds'; end if;

    insert into public.wallet_transactions (user_id, kind, diamonds_delta, ref_type, ref_id, note)
      values (_uid, 'shop_purchase', -_t.price_diamonds, 'theme', _t.id,
              'Bought ' || _t.name);
  end if;

  if _t.duration_days is not null and _t.duration_days > 0 then
    _expires := now() + (_t.duration_days || ' days')::interval;
  else
    _expires := null;
  end if;

  insert into public.user_themes (user_id, theme_id, expires_at, purchased_price_diamonds)
    values (_uid, _theme_id, _expires, _t.price_diamonds)
    on conflict (user_id, theme_id) do update
      set expires_at = case
            when public.user_themes.expires_at is null then null
            when excluded.expires_at is null then null
            else greatest(public.user_themes.expires_at, now()) + (_t.duration_days || ' days')::interval
          end,
          purchased_price_diamonds = _t.price_diamonds
    returning * into _row;

  return _row;
end $$;


--
-- Name: purchase_shop_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_shop_item(_theme_id uuid, _currency text DEFAULT 'auto'::text) RETURNS public.user_themes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _t public.themes%rowtype;
  _cur text;
  _price int;
  _expires timestamptz;
  _row public.user_themes;
begin
  if _uid is null then raise exception 'Sign in to buy'; end if;
  select * into _t from public.themes where id = _theme_id and is_active;
  if not found then raise exception 'Item not found'; end if;

  _cur := lower(coalesce(_currency, 'auto'));
  if _cur = 'auto' then
    _cur := case when _t.price_diamonds > 0 then 'diamonds' else 'coins' end;
  end if;
  if _cur not in ('coins','diamonds') then
    raise exception 'Invalid currency';
  end if;

  _price := case when _cur = 'diamonds' then _t.price_diamonds else _t.price end;
  if _price < 0 then raise exception 'Invalid price'; end if;

  if _price > 0 then
    if _cur = 'diamonds' then
      update public.profiles
         set diamonds = diamonds - _price, updated_at = now()
       where id = _uid and diamonds >= _price;
      if not found then raise exception 'Not enough diamonds'; end if;
      insert into public.wallet_transactions (user_id, kind, diamonds_delta, ref_type, ref_id, note)
        values (_uid, 'shop_purchase', -_price, 'theme', _t.id, 'Bought ' || _t.name);
    else
      update public.profiles
         set coins = coins - _price, updated_at = now()
       where id = _uid and coins >= _price;
      if not found then raise exception 'Not enough coins'; end if;
      insert into public.wallet_transactions (user_id, kind, coins_delta, ref_type, ref_id, note)
        values (_uid, 'shop_purchase', -_price, 'theme', _t.id, 'Bought ' || _t.name);
    end if;
  end if;

  if _t.duration_days is not null and _t.duration_days > 0 then
    _expires := now() + (_t.duration_days || ' days')::interval;
  else
    _expires := null;
  end if;

  insert into public.user_themes (user_id, theme_id, expires_at, purchased_price_diamonds)
    values (_uid, _theme_id, _expires,
            case when _cur = 'diamonds' then _price else 0 end)
    on conflict (user_id, theme_id) do update
      set expires_at = case
            when public.user_themes.expires_at is null then null
            when excluded.expires_at is null then null
            else greatest(public.user_themes.expires_at, now()) + (_t.duration_days || ' days')::interval
          end,
          purchased_price_diamonds = case when _cur = 'diamonds' then _price else public.user_themes.purchased_price_diamonds end
    returning * into _row;

  return _row;
end $$;


--
-- Name: purchase_theme(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_theme(_theme_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _theme public.themes%ROWTYPE;
  _owns BOOLEAN;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to buy themes'; END IF;
  SELECT * INTO _theme FROM public.themes WHERE id = _theme_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Theme not found'; END IF;

  SELECT EXISTS(SELECT 1 FROM public.user_themes WHERE user_id = _uid AND theme_id = _theme_id)
    INTO _owns;

  IF NOT _owns AND NOT _theme.is_free THEN
    UPDATE public.profiles
      SET coins = coins - _theme.price, updated_at = now()
      WHERE id = _uid AND coins >= _theme.price;
    IF NOT FOUND THEN RAISE EXCEPTION 'Not enough coins'; END IF;
    INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
      VALUES (_uid, 'theme', -_theme.price, 'Bought theme ' || _theme.name);
  END IF;

  INSERT INTO public.user_themes (user_id, theme_id)
    VALUES (_uid, _theme_id) ON CONFLICT DO NOTHING;

  UPDATE public.profiles SET theme_id = _theme_id, updated_at = now() WHERE id = _uid;
END;
$$;


--
-- Name: purchase_vip(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_vip(_tier_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _tier public.vip_tiers%ROWTYPE;
  _base TIMESTAMPTZ;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to buy VIP'; END IF;
  SELECT * INTO _tier FROM public.vip_tiers WHERE id = _tier_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'VIP tier not found'; END IF;

  UPDATE public.profiles
    SET coins = coins - _tier.price
    WHERE id = _uid AND coins >= _tier.price;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not enough coins'; END IF;

  SELECT GREATEST(now(), COALESCE(vip_expiry, now())) INTO _base
    FROM public.profiles WHERE id = _uid;

  UPDATE public.profiles
    SET is_vip = true,
        vip_expiry = _base + (_tier.duration_days || ' days')::interval,
        level = level + _tier.level_boost,
        updated_at = now()
    WHERE id = _uid;

  INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
    VALUES (_uid, 'vip', -_tier.price, 'Bought VIP ' || _tier.name);
END;
$$;


--
-- Name: rank_gifters(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rank_gifters(p_period text DEFAULT 'all'::text, p_scope text DEFAULT 'global'::text, p_scope_value text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(user_id uuid, username text, avatar text, country text, vip_level integer, total_coins bigint, rnk bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH agg AS (
    SELECT g.sender_id AS uid, SUM(g.coins_spent)::bigint AS total
      FROM public.gift_sends g
      JOIN public.profiles   p ON p.id = g.sender_id
 LEFT JOIN public.family_members fm ON fm.user_id = g.sender_id
     WHERE g.sender_id IS NOT NULL
       AND g.created_at >= public.vip_period_start(p_period)
       AND (p_scope = 'global'
            OR (p_scope = 'country' AND p.country = p_scope_value)
            OR (p_scope = 'family'  AND fm.family_id::text = p_scope_value))
     GROUP BY g.sender_id
  )
  SELECT a.uid, p.username, p.avatar, p.country, COALESCE(p.vip_level,0), a.total,
         ROW_NUMBER() OVER (ORDER BY a.total DESC) AS rnk
    FROM agg a JOIN public.profiles p ON p.id = a.uid
   ORDER BY a.total DESC
   LIMIT p_limit;
$$;


--
-- Name: rank_hosts(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rank_hosts(p_period text DEFAULT 'all'::text, p_scope text DEFAULT 'global'::text, p_scope_value text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(user_id uuid, username text, avatar text, country text, vip_level integer, total_coins bigint, rnk bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH agg AS (
    SELECT g.receiver_id AS uid, SUM(g.coins_spent)::bigint AS total
      FROM public.gift_sends g
      JOIN public.profiles   p ON p.id = g.receiver_id
 LEFT JOIN public.family_members fm ON fm.user_id = g.receiver_id
     WHERE g.receiver_id IS NOT NULL
       AND g.created_at >= public.vip_period_start(p_period)
       AND (p_scope = 'global'
            OR (p_scope = 'country' AND p.country = p_scope_value)
            OR (p_scope = 'family'  AND fm.family_id::text = p_scope_value))
     GROUP BY g.receiver_id
  )
  SELECT a.uid, p.username, p.avatar, p.country, COALESCE(p.vip_level,0), a.total,
         ROW_NUMBER() OVER (ORDER BY a.total DESC) AS rnk
    FROM agg a JOIN public.profiles p ON p.id = a.uid
   ORDER BY a.total DESC
   LIMIT p_limit;
$$;


--
-- Name: recharge_initiate(uuid, public.recharge_pay_method, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recharge_initiate(_package_id uuid, _method public.recharge_pay_method, _account_ref text) RETURNS TABLE(order_id uuid, otp_code text, expires_at timestamp with time zone, amount_pkr numeric, coins_total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _pkg public.coin_packages%rowtype;
  _otp text;
  _order public.recharge_orders%rowtype;
begin
  if auth.uid() is null then raise exception 'Auth required'; end if;

  select * into _pkg from public.coin_packages where id = _package_id and active for update;
  if not found then raise exception 'Package not found'; end if;

  if _account_ref is null or length(trim(_account_ref)) < 4 then
    raise exception 'Valid account/phone required';
  end if;

  _otp := lpad((floor(random() * 1000000))::int::text, 6, '0');

  insert into public.recharge_orders
    (user_id, package_id, method, account_ref, amount_pkr, coins_total, otp_code)
  values
    (auth.uid(), _pkg.id, _method, trim(_account_ref),
     _pkg.price_pkr, _pkg.coins + _pkg.bonus_coins, _otp)
  returning * into _order;

  return query select _order.id, _order.otp_code, _order.otp_expires_at,
                      _order.amount_pkr, _order.coins_total;
end $$;


--
-- Name: recharge_requests_sync_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recharge_requests_sync_aliases() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- amount
  if new.amount_pkr is null and new.amount_paid is not null then
    new.amount_pkr := new.amount_paid;
  elsif new.amount_paid is null and new.amount_pkr is not null then
    new.amount_paid := new.amount_pkr;
  end if;

  -- coins
  if new.coins_expected is null and new.coins is not null then
    new.coins_expected := new.coins;
  elsif new.coins is null and new.coins_expected is not null then
    new.coins := new.coins_expected;
  end if;

  -- proof url ↔ image
  if new.proof_url is null and new.proof_image is not null then
    new.proof_url := new.proof_image;
  elsif new.proof_image is null and new.proof_url is not null then
    new.proof_image := new.proof_url;
  end if;

  -- sender account ↔ number
  if new.sender_account is null and new.sender_number is not null then
    new.sender_account := new.sender_number;
  elsif new.sender_number is null and new.sender_account is not null then
    new.sender_number := new.sender_account;
  end if;

  -- txn reference ↔ id
  if new.txn_reference is null and new.txn_id is not null then
    new.txn_reference := new.txn_id;
  elsif new.txn_id is null and new.txn_reference is not null then
    new.txn_id := new.txn_reference;
  end if;

  return new;
end;
$$;


--
-- Name: recharge_verify_otp(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recharge_verify_otp(_order_id uuid, _otp text) RETURNS TABLE(success boolean, coins_credited integer, new_balance bigint, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _order public.recharge_orders%rowtype;
  _req_id uuid;
  _method_text text;
  _pay_method public.pay_method;
  admin_row record;
begin
  if auth.uid() is null then raise exception 'Auth required'; end if;

  select * into _order from public.recharge_orders
    where id = _order_id and user_id = auth.uid() for update;
  if not found then raise exception 'Order not found'; end if;

  if _order.status <> 'pending_otp' then
    return query select false, 0, 0::bigint, 'Order already processed'::text;
    return;
  end if;

  if now() > _order.otp_expires_at then
    update public.recharge_orders set status = 'expired' where id = _order.id;
    return query select false, 0, 0::bigint, 'OTP expired'::text;
    return;
  end if;

  if _order.otp_attempts >= 5 then
    update public.recharge_orders set status = 'failed' where id = _order.id;
    return query select false, 0, 0::bigint, 'Too many attempts'::text;
    return;
  end if;

  if _order.otp_code <> _otp then
    update public.recharge_orders set otp_attempts = otp_attempts + 1 where id = _order.id;
    return query select false, 0, 0::bigint, 'Invalid OTP'::text;
    return;
  end if;

  -- OTP verified — mark order as completed but DO NOT credit yet
  update public.recharge_orders
     set status = 'completed', completed_at = now()
   where id = _order.id;

  -- Map recharge_pay_method → pay_method (enum used by recharge_requests)
  _method_text := _order.method::text;
  begin
    _pay_method := _method_text::public.pay_method;
  exception when others then
    _pay_method := 'manual'::public.pay_method;
  end;

  -- Idempotency: if we've already submitted this order for approval, reuse it
  select id into _req_id from public.recharge_requests where order_id = _order.id;
  if _req_id is null then
    insert into public.recharge_requests
      (user_id, package_id, amount_paid, coins, method, sender_account,
       txn_reference, note, status, amount_pkr, coins_expected, order_id)
    values
      (_order.user_id, _order.package_id, _order.amount_pkr, _order.coins_total,
       _pay_method, _order.account_ref,
       'OTP:' || _order.id::text,
       'Auto-OTP verified · pending admin approval',
       'pending'::public.recharge_status,
       _order.amount_pkr, _order.coins_total, _order.id)
    returning id into _req_id;

    -- Notify all admins
    for admin_row in
      select distinct ur.user_id
        from public.user_roles ur
       where ur.role in ('admin'::public.app_role, 'super_admin'::public.app_role)
    loop
      begin
        insert into public.notifications
          (user_id, kind, title, body, data, actor_id, entity_type, entity_id)
        values
          (admin_row.user_id, 'system_broadcast',
           'New recharge pending approval',
           'Rs ' || _order.amount_pkr::text || ' · ' || _order.coins_total::text || ' coins',
           jsonb_build_object('recharge_request_id', _req_id, 'order_id', _order.id),
           _order.user_id, 'recharge_request', _req_id::text);
      exception when others then null;
      end;
    end loop;
  end if;

  return query select
    true,
    0,                                    -- no coins credited yet
    coalesce((select coins from public.profiles where id = _order.user_id), 0::bigint),
    'OTP verified. Waiting for admin approval — coins will be credited once approved.'::text;
end $$;


--
-- Name: reject_custom_theme(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_custom_theme(_id uuid, _reason text DEFAULT NULL::text) RETURNS public.custom_themes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  row public.custom_themes;
begin
  if not public.is_admin(me) then raise exception 'admin only'; end if;

  update public.custom_themes
     set status = 'rejected',
         reviewed_by = me,
         reviewed_at = now(),
         admin_notes = _reason
   where id = _id and status = 'pending'
   returning * into row;
  if row.id is null then raise exception 'request not found or already reviewed'; end if;

  update public.profiles set coins = coins + row.coins_paid, updated_at = now() where id = row.user_id;

  insert into public.notifications
    (user_id, kind, title, body, data, actor_id, entity_type, entity_id)
  values
    (row.user_id, 'account_action',
     'Custom theme rejected',
     coalesce(_reason, 'Your submission was not approved. Coins have been refunded.'),
     jsonb_build_object('custom_theme_id', row.id, 'refunded', row.coins_paid),
     me, 'custom_theme', row.id::text);

  return row;
end $$;


--
-- Name: reject_recharge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_recharge(_request_id uuid, _admin_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'Only admins can reject recharges';
  end if;

  update public.recharge_requests
    set status = 'rejected',
        processed_at = now(),
        admin_note = _admin_note
    where id = _request_id and status = 'pending';

  if not found then
    raise exception 'Recharge request not found or already processed';
  end if;
end;
$$;


--
-- Name: reject_withdrawal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_withdrawal(_request_id uuid, _note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _req public.withdrawal_requests%ROWTYPE;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Only admins can reject withdrawals'; END IF;
  SELECT * INTO _req FROM public.withdrawal_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Withdrawal not found'; END IF;
  IF _req.status <> 'pending' THEN RAISE EXCEPTION 'Withdrawal already processed'; END IF;

  UPDATE public.withdrawal_requests SET status = 'rejected', processed_at = now(), admin_note = _note
    WHERE id = _request_id;
  -- refund the held diamonds
  UPDATE public.profiles SET diamonds = diamonds + _req.diamonds, updated_at = now() WHERE id = _req.user_id;
  INSERT INTO public.wallet_transactions (user_id, kind, diamonds, note)
    VALUES (_req.user_id, 'withdraw_refund', _req.diamonds, 'Withdrawal rejected — refunded');
END;
$$;


--
-- Name: request_seat(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_seat(_room_id uuid, _seat_index integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  host uuid;
  seat_taken boolean;
  locked int[];
  req_id uuid;
begin
  if me is null then raise exception 'not authenticated'; end if;

  select host_id, locked_seats into host, locked from public.live_rooms where id = _room_id;
  if host is null then raise exception 'room not found'; end if;
  if host = me then raise exception 'you are the host'; end if;

  if _seat_index is not null then
    if _seat_index = 0 then raise exception 'seat 1 is for host'; end if;
    if locked is not null and _seat_index = any(locked) then raise exception 'seat is locked'; end if;
    select exists(
      select 1 from public.room_members
      where room_id = _room_id and seat_index = _seat_index
    ) into seat_taken;
    if seat_taken then raise exception 'seat already taken'; end if;
  end if;

  -- Reuse existing pending row if present.
  select id into req_id from public.seat_requests
    where room_id = _room_id and from_user = me and status = 'pending';
  if req_id is not null then
    update public.seat_requests set seat_index = _seat_index, created_at = now()
      where id = req_id;
    return req_id;
  end if;

  insert into public.seat_requests (room_id, from_user, seat_index)
    values (_room_id, me, _seat_index)
    returning id into req_id;
  return req_id;
end $$;


--
-- Name: request_withdrawal(bigint, public.pay_method, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal(_diamonds bigint, _method public.pay_method, _account_number text, _account_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _rate numeric;
  _amount numeric;
  _id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to withdraw'; END IF;
  IF _diamonds < 1 THEN RAISE EXCEPTION 'Invalid amount'; END IF;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = _uid AND is_free) THEN
    RAISE EXCEPTION 'Free accounts cannot withdraw';
  END IF;

  SELECT diamond_price_pkr INTO _rate FROM public.app_settings WHERE id = 'global';
  _amount := ROUND(_diamonds * COALESCE(_rate, 0.5), 2);

  UPDATE public.profiles SET diamonds = diamonds - _diamonds, updated_at = now()
    WHERE id = _uid AND diamonds >= _diamonds;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not enough diamonds'; END IF;

  INSERT INTO public.withdrawal_requests (user_id, diamonds, amount_pkr, method, account_number, account_name)
    VALUES (_uid, _diamonds, _amount, _method, _account_number, _account_name)
    RETURNING id INTO _id;

  INSERT INTO public.wallet_transactions (user_id, kind, diamonds, note)
    VALUES (_uid, 'withdraw', -_diamonds, 'Withdrawal requested');

  RETURN _id;
END;
$$;


--
-- Name: respond_seat_request(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_seat_request(_request_id uuid, _accept boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  req record;
  is_host boolean;
  is_mod boolean;
  target_seat int;
  seat_max int;
  i int;
begin
  if me is null then raise exception 'not authenticated'; end if;

  select * into req from public.seat_requests where id = _request_id;
  if not found then raise exception 'request not found'; end if;
  if req.status <> 'pending' then raise exception 'request already handled'; end if;

  select (r.host_id = me) into is_host from public.live_rooms r where r.id = req.room_id;
  select coalesce(m.is_moderator, false) into is_mod
    from public.room_members m
    where m.room_id = req.room_id and m.user_id = me;
  if not (coalesce(is_host, false) or coalesce(is_mod, false)) then
    raise exception 'only host or moderator can respond';
  end if;

  if not _accept then
    update public.seat_requests
      set status = 'rejected', responded_at = now(), responded_by = me
      where id = _request_id;
    return -1;
  end if;

  -- Pick seat: requested or first free (skip seat 0 = host).
  if req.seat_index is not null then
    target_seat := req.seat_index;
    if exists (
      select 1 from public.room_members
      where room_id = req.room_id and seat_index = target_seat
    ) then
      raise exception 'seat already taken';
    end if;
  else
    select seat_count into seat_max from public.live_rooms where id = req.room_id;
    target_seat := null;
    for i in 1 .. coalesce(seat_max, 8) - 1 loop
      if not exists (
        select 1 from public.room_members
        where room_id = req.room_id and seat_index = i
      ) then
        target_seat := i;
        exit;
      end if;
    end loop;
    if target_seat is null then raise exception 'no free seat'; end if;
  end if;

  -- Mark accepted FIRST so the seat-guard trigger sees the accepted invite equivalent.
  update public.seat_requests
    set status = 'accepted', responded_at = now(), responded_by = me, seat_index = target_seat
    where id = _request_id;

  -- Insert as SECURITY DEFINER (auth.uid() is host/mod, not requester),
  -- so the self-seat-claim guard trigger is bypassed (NEW.user_id <> me).
  insert into public.room_members (room_id, user_id, seat_index)
    values (req.room_id, req.from_user, target_seat)
    on conflict (room_id, user_id) do update
      set seat_index = excluded.seat_index;

  return target_seat;
end $$;


--
-- Name: room_end(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_end(_room_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _host uuid;
BEGIN
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF _host IS NULL THEN RAISE EXCEPTION 'Room not found'; END IF;
  IF auth.uid() <> _host THEN RAISE EXCEPTION 'Only the host can end the room'; END IF;

  UPDATE public.rooms
    SET is_live = false, ended_at = now(), viewers = 0
    WHERE id = _room_id;

  -- Terminate the session for everyone in the room.
  DELETE FROM public.room_participants WHERE room_id = _room_id;
END;
$$;


--
-- Name: room_kick_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_kick_user(_room_id uuid, _user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _host uuid; _is_mod boolean;
BEGIN
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF _host IS NULL THEN RAISE EXCEPTION 'Room not found'; END IF;
  SELECT is_moderator INTO _is_mod FROM public.room_participants
    WHERE room_id = _room_id AND user_id = auth.uid();
  IF auth.uid() <> _host AND COALESCE(_is_mod, false) = false THEN
    RAISE EXCEPTION 'Only the host or a moderator can remove users';
  END IF;
  IF _user_id = _host THEN RAISE EXCEPTION 'The host cannot be removed'; END IF;
  DELETE FROM public.room_participants WHERE room_id = _room_id AND user_id = _user_id;
  INSERT INTO public.room_bans (room_id, user_id)
    VALUES (_room_id, _user_id) ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: room_leave_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_leave_seat(_room_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid(); _host uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF _uid = _host THEN RAISE EXCEPTION 'The host stays on stage'; END IF;
  UPDATE public.room_participants
    SET seat_status = 'viewer', updated_at = now()
    WHERE room_id = _room_id AND user_id = _uid;
END;
$$;


--
-- Name: room_manage_seat(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_manage_seat(_room_id uuid, _user_id uuid, _status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _host uuid; _is_mod boolean;
BEGIN
  IF _status NOT IN ('viewer', 'speaker') THEN
    RAISE EXCEPTION 'Invalid seat status';
  END IF;
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF _host IS NULL THEN RAISE EXCEPTION 'Room not found'; END IF;
  SELECT is_moderator INTO _is_mod FROM public.room_participants
    WHERE room_id = _room_id AND user_id = auth.uid();
  IF auth.uid() <> _host AND COALESCE(_is_mod, false) = false THEN
    RAISE EXCEPTION 'Only the host or a moderator can manage the stage';
  END IF;
  IF _user_id = _host THEN RAISE EXCEPTION 'The host is always on stage'; END IF;
  UPDATE public.room_participants
    SET seat_status = _status, updated_at = now()
    WHERE room_id = _room_id AND user_id = _user_id;
END;
$$;


--
-- Name: room_request_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_request_seat(_room_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  UPDATE public.room_participants
    SET seat_status = 'requested', updated_at = now()
    WHERE room_id = _room_id AND user_id = _uid AND seat_status = 'viewer';
END;
$$;


--
-- Name: room_set_moderator(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_set_moderator(_room_id uuid, _user_id uuid, _value boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _host uuid;
BEGIN
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF _host IS NULL THEN RAISE EXCEPTION 'Room not found'; END IF;
  IF auth.uid() <> _host THEN RAISE EXCEPTION 'Only the host can assign moderators'; END IF;
  UPDATE public.room_participants
    SET is_moderator = _value, updated_at = now()
    WHERE room_id = _room_id AND user_id = _user_id;
END;
$$;


--
-- Name: room_top_gifters(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_top_gifters(_room_id uuid, _limit integer DEFAULT 20) RETURNS TABLE(user_id uuid, username text, avatar text, total_coins bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    gs.sender_id as user_id,
    p.username,
    p.avatar,
    sum(gs.coins_spent)::bigint as total_coins
  from public.gift_sends gs
  left join public.profiles p on p.id = gs.sender_id
  where gs.room_id = _room_id
    and gs.sender_id is not null
  group by gs.sender_id, p.username, p.avatar
  order by total_coins desc
  limit _limit;
$$;


--
-- Name: send_broadcast(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_broadcast(_title text, _body text, _target text DEFAULT 'all'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _count int := 0;
begin
  if not public.has_role(auth.uid(), 'admin')
     and not public.has_role(auth.uid(), 'super_admin') then
    raise exception 'admins only';
  end if;
  if _target = 'vip' then
    insert into public.notifications(user_id, kind, title, body)
    select id, 'system_broadcast', _title, _body from public.profiles where is_vip = true;
  elsif _target = 'hosts' then
    insert into public.notifications(user_id, kind, title, body)
    select ur.user_id, 'system_broadcast', _title, _body
    from public.user_roles ur where ur.role = 'host';
  else
    insert into public.notifications(user_id, kind, title, body)
    select id, 'system_broadcast', _title, _body from public.profiles;
  end if;
  get diagnostics _count = row_count;
  return _count;
end $$;


--
-- Name: send_gift(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_gift(_room_id uuid, _gift_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid UUID := auth.uid();
  _gift public.gifts%ROWTYPE;
  _sender_name TEXT;
  _host UUID;
  _host_share bigint;
  _admin_share bigint;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to send gifts'; END IF;
  SELECT * INTO _gift FROM public.gifts WHERE id = _gift_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Gift not found'; END IF;
  SELECT host_id INTO _host FROM public.rooms WHERE id = _room_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room not found'; END IF;

  UPDATE public.profiles SET coins = coins - _gift.price, updated_at = now()
    WHERE id = _uid AND coins >= _gift.price RETURNING username INTO _sender_name;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not enough coins'; END IF;

  _host_share := floor(_gift.price * 0.6);
  _admin_share := _gift.price - _host_share;
  UPDATE public.profiles SET diamonds = diamonds + _host_share, updated_at = now() WHERE id = _host;
  UPDATE public.app_settings SET platform_diamonds = platform_diamonds + _admin_share WHERE id = 'global';

  UPDATE public.rooms SET total_points = total_points + _gift.price WHERE id = _room_id;

  INSERT INTO public.wallet_transactions (user_id, kind, coins, note)
    VALUES (_uid, 'gift', -_gift.price, 'Sent ' || _gift.name);
  INSERT INTO public.wallet_transactions (user_id, kind, diamonds, note)
    VALUES (_host, 'gift_earning', _host_share, 'Received ' || _gift.name);
  INSERT INTO public.gift_events (room_id, sender_id, sender_name, gift_id, gift_emoji, gift_name, coins)
    VALUES (_room_id, _uid, COALESCE(_sender_name, 'Guest'), _gift.id, _gift.emoji, _gift.name, _gift.price);
  INSERT INTO public.room_messages (room_id, user_id, username, message, kind)
    VALUES (_room_id, _uid, COALESCE(_sender_name, 'Guest'), 'sent a ' || _gift.emoji || ' ' || _gift.name || '!', 'gift');
END;
$$;


--
-- Name: gift_sends; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gift_sends (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    room_id uuid,
    sender_id uuid NOT NULL,
    receiver_id uuid NOT NULL,
    gift_id uuid NOT NULL,
    quantity integer DEFAULT 1 NOT NULL,
    coins_spent bigint NOT NULL,
    diamonds_earned bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finalized_at timestamp with time zone,
    CONSTRAINT gift_sends_quantity_check CHECK ((quantity > 0))
);

ALTER TABLE ONLY public.gift_sends REPLICA IDENTITY FULL;


--
-- Name: send_gift(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_gift(_room_id uuid, _receiver_id uuid, _gift_id uuid, _quantity integer DEFAULT 1) RETURNS public.gift_sends
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sender uuid := auth.uid();
  g public.gifts%ROWTYPE;
  host_share constant numeric := 0.6;
  total_coins bigint;
  diamonds_earned bigint;
  new_sender_coins bigint;
  send_row public.gift_sends;
BEGIN
  IF sender IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF;
  IF _quantity IS NULL OR _quantity < 1 THEN _quantity := 1; END IF;
  IF _receiver_id = sender THEN RAISE EXCEPTION 'cannot gift yourself'; END IF;

  SELECT * INTO g FROM public.gifts WHERE id = _gift_id AND COALESCE(active, is_active);
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;

  total_coins := COALESCE(g.price_coins, g.price)::bigint * _quantity;
  diamonds_earned := floor(total_coins * host_share)::bigint
                     + (COALESCE(g.diamonds_value, 0)::bigint * _quantity);

  UPDATE public.profiles
     SET coins = coins - total_coins
   WHERE id = sender AND coins >= total_coins
   RETURNING coins INTO new_sender_coins;
  IF NOT FOUND THEN RAISE EXCEPTION 'insufficient coins'; END IF;

  UPDATE public.profiles
     SET diamonds = diamonds + diamonds_earned
   WHERE id = _receiver_id;

  INSERT INTO public.gift_sends
    (room_id, sender_id, receiver_id, gift_id, quantity, coins_spent, diamonds_earned)
  VALUES
    (_room_id, sender, _receiver_id, _gift_id, _quantity, total_coins, diamonds_earned)
  RETURNING * INTO send_row;

  INSERT INTO public.wallet_transactions
    (user_id, kind, coins_delta, balance_coins_after, ref_type, ref_id, note)
  VALUES
    (sender, 'gift_sent', -total_coins, new_sender_coins, 'gift', send_row.id,
     'Sent ' || _quantity || 'x ' || g.name);

  INSERT INTO public.wallet_transactions
    (user_id, kind, diamonds_delta, ref_type, ref_id, note)
  VALUES
    (_receiver_id, 'gift_received', diamonds_earned, 'gift', send_row.id,
     'Received ' || _quantity || 'x ' || g.name);

  IF _room_id IS NOT NULL THEN
    INSERT INTO public.room_messages (room_id, user_id, kind, text, message, meta)
    VALUES (_room_id, sender, 'gift', g.name, g.name,
      jsonb_build_object(
        'giftId', g.id, 'giftName', g.name, 'icon', COALESCE(g.icon, g.emoji),
        'quantity', _quantity, 'coins', total_coins,
        'receiverId', _receiver_id, 'animation', g.animation
      ));
  END IF;

  RETURN send_row;
END $$;


--
-- Name: send_host_love(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_host_love(_host uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  last_at timestamptz;
  cost int := 100;
begin
  if me is null then
    raise exception 'auth required';
  end if;
  if me = _host then
    raise exception 'cannot love yourself';
  end if;

  select max(created_at) into last_at
    from public.host_love_hearts
    where from_user = me and to_host = _host;

  if last_at is not null and last_at > now() - interval '24 hours' then
    raise exception 'cooldown' using hint = to_char(last_at + interval '24 hours', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  end if;

  update public.profiles
     set coins = coins - cost
   where id = me and coins >= cost;
  if not found then
    raise exception 'insufficient coins';
  end if;

  update public.profiles
     set diamonds = diamonds + 1
   where id = _host;

  insert into public.host_love_hearts(from_user, to_host, coins_spent)
  values (me, _host, cost);

  return now() + interval '24 hours';
end;
$$;


--
-- Name: send_room_gift(uuid, text, text, integer, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_room_gift(_room_id uuid, _emoji text, _name text, _price integer, _target text, _target_id uuid DEFAULT NULL::uuid, _gift_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sender uuid := auth.uid();
  host uuid;
  new_coins bigint;
  diamonds_earned bigint;
  host_share constant numeric := 0.6;
BEGIN
  IF sender IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF _price < 0 THEN RAISE EXCEPTION 'invalid price'; END IF;

  SELECT host_id INTO host FROM public.live_rooms WHERE id = _room_id;
  IF host IS NULL THEN RAISE EXCEPTION 'Room not found'; END IF;

  diamonds_earned := floor(_price * host_share);

  UPDATE public.profiles SET coins = coins - _price
   WHERE id = sender AND coins >= _price
   RETURNING coins INTO new_coins;
  IF NOT FOUND THEN RAISE EXCEPTION 'insufficient coins'; END IF;

  INSERT INTO public.wallet_transactions
    (user_id, kind, coins_delta, balance_coins_after, ref_type, ref_id, note)
  VALUES
    (sender, 'gift_sent', -_price, new_coins, 'room_gift', _room_id,
     'Sent ' || _name || COALESCE(' ' || _emoji, ''));

  INSERT INTO public.room_messages (room_id, user_id, kind, text, message, meta)
  VALUES (_room_id, sender, 'gift', _name, _name,
    jsonb_build_object(
      'giftId', _gift_id, 'giftName', _name, 'icon', _emoji,
      'quantity', 1, 'coins', _price,
      'receiverId', COALESCE(_target_id, host)
    ));
END;
$$;


