--
-- Name: daily_spins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.daily_spins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    prize_id uuid,
    reward_kind text NOT NULL,
    reward_amount integer DEFAULT 0 NOT NULL,
    reward_label text NOT NULL,
    granted_theme_id uuid,
    next_spin_at timestamp with time zone NOT NULL,
    spun_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: spin_daily_wheel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spin_daily_wheel() RETURNS public.daily_spins
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  cooldown int;
  enabled boolean;
  last_next timestamptz;
  total_w int;
  r int;
  cum int := 0;
  chosen public.spin_prizes%rowtype;
  amount int;
  reward_theme uuid;
  spin public.daily_spins;
begin
  if me is null then raise exception 'not authenticated'; end if;

  select daily_spin_cooldown_hours, daily_spin_enabled
    into cooldown, enabled
    from public.app_settings where id = 'global';
  if not coalesce(enabled, true) then raise exception 'daily spin is currently disabled'; end if;

  select next_spin_at into last_next
    from public.daily_spins where user_id = me
   order by spun_at desc limit 1;
  if last_next is not null and last_next > now() then
    raise exception 'next spin available at %', last_next;
  end if;

  select coalesce(sum(weight), 0) into total_w from public.spin_prizes where is_active;
  if total_w <= 0 then raise exception 'no prizes configured'; end if;

  -- server-side weighted random
  r := 1 + floor(random() * total_w)::int;
  for chosen in
    select * from public.spin_prizes where is_active order by sort, id
  loop
    cum := cum + chosen.weight;
    if r <= cum then exit; end if;
  end loop;

  amount := chosen.min_amount
          + floor(random() * (greatest(chosen.max_amount - chosen.min_amount, 0) + 1))::int;
  reward_theme := null;

  if chosen.kind = 'coins' then
    update public.profiles set coins = coins + amount, updated_at = now() where id = me;
  elsif chosen.kind = 'diamonds' then
    update public.profiles set diamonds = coalesce(diamonds, 0) + amount, updated_at = now() where id = me;
  elsif chosen.kind in ('theme','frame') then
    select t.id into reward_theme
      from public.themes t
      join public.theme_categories c on c.id = t.category_id
     where t.is_active
       and lower(c.slug) = case when chosen.kind = 'frame' then 'frame' else 'theme' end
     order by random() limit 1;
    if reward_theme is not null then
      insert into public.user_themes (user_id, theme_id)
        values (me, reward_theme)
        on conflict (user_id, theme_id) do nothing;
    end if;
  end if;

  insert into public.daily_spins
    (user_id, prize_id, reward_kind, reward_amount, reward_label, granted_theme_id, next_spin_at)
  values
    (me, chosen.id, chosen.kind, amount, chosen.label, reward_theme,
     now() + (coalesce(cooldown, 24) || ' hours')::interval)
  returning * into spin;

  return spin;
end $$;


--
-- Name: submit_custom_theme(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_custom_theme(_image_url text) RETURNS public.custom_themes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  price int;
  dur_h int;
  enabled boolean;
  bal bigint;
  row public.custom_themes;
  admin_row record;
begin
  if me is null then raise exception 'not authenticated'; end if;
  if _image_url is null or length(_image_url) < 5 then raise exception 'invalid image url'; end if;

  select custom_theme_price_coins, custom_theme_duration_hours, custom_theme_enabled
    into price, dur_h, enabled
    from public.app_settings where id = 'global';
  if not coalesce(enabled, true) then raise exception 'custom theme submissions are disabled'; end if;

  -- refuse if user already has a pending submission
  if exists (select 1 from public.custom_themes where user_id = me and status = 'pending') then
    raise exception 'you already have a pending submission';
  end if;

  select coins into bal from public.profiles where id = me for update;
  if coalesce(bal, 0) < price then raise exception 'not enough coins (need %)', price; end if;

  update public.profiles set coins = coins - price, updated_at = now() where id = me;

  insert into public.custom_themes (user_id, image_url, coins_paid)
    values (me, _image_url, price)
    returning * into row;

  for admin_row in
    select distinct ur.user_id
      from public.user_roles ur
     where ur.role in ('admin'::public.app_role, 'super_admin'::public.app_role)
  loop
    insert into public.notifications
      (user_id, kind, title, body, data, actor_id, entity_type, entity_id)
    values
      (admin_row.user_id, 'system_broadcast',
       'New custom theme pending',
       'A user submitted a custom background for approval',
       jsonb_build_object('custom_theme_id', row.id),
       me, 'custom_theme', row.id::text);
  end loop;

  return row;
end $$;


--
-- Name: sync_room_message_text(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_room_message_text() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.text := coalesce(new.text, nullif(new.message, ''));
  new.message := coalesce(nullif(new.message, ''), new.text, '');
  return new;
end;
$$;


--
-- Name: take_seat(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_seat(_room_id uuid, _seat_index integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  r_host uuid;
  r_locked int[];
begin
  if me is null then raise exception 'not authenticated'; end if;

  select host_id, locked_seats into r_host, r_locked
    from public.live_rooms where id = _room_id;
  if r_host is null then raise exception 'room not found'; end if;

  -- Seat 0 = host only
  if _seat_index = 0 and me <> r_host then
    raise exception 'Seat 1 is reserved for the host';
  end if;

  -- Locked seat: only host / moderator can occupy
  if _seat_index = any(coalesce(r_locked, '{}'::int[])) then
    if me <> r_host and not exists (
      select 1 from public.room_members
      where room_id = _room_id and user_id = me and is_moderator = true
    ) then
      raise exception 'Seat is locked';
    end if;
  end if;

  -- Host moving off seat 0 → free seat 0 (row stays with seat_index=null)
  if me = r_host and _seat_index <> 0 then
    update public.room_members set seat_index = null
     where room_id = _room_id and seat_index = 0 and user_id = me;
  end if;

  insert into public.room_members (room_id, user_id, seat_index)
    values (_room_id, me, _seat_index)
    on conflict (room_id, user_id) do update
      set seat_index = excluded.seat_index;
end $$;


--
-- Name: tg_gift_sender_level_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_gift_sender_level_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_total bigint;
  v_old_level int;
  v_new_level int;
  v_tier      text;
  v_title     text;
  v_next_thresh bigint;
  v_cur_thresh  bigint;
BEGIN
  IF NEW.sender_id IS NULL OR COALESCE(NEW.coins_spent, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  UPDATE public.profiles
     SET total_gifted_coins = COALESCE(total_gifted_coins, 0) + NEW.coins_spent
   WHERE id = NEW.sender_id
   RETURNING total_gifted_coins, COALESCE(vip_level,0) INTO v_new_total, v_old_level;

  IF v_new_total IS NULL THEN RETURN NEW; END IF;

  -- compute level from config (largest threshold <= total)
  SELECT level, tier, title, threshold_coins
    INTO v_new_level, v_tier, v_title, v_cur_thresh
    FROM public.vip_level_config
   WHERE threshold_coins <= v_new_total
   ORDER BY level DESC LIMIT 1;

  IF v_new_level IS NULL THEN v_new_level := 0; END IF;
  -- never decrease
  v_new_level := GREATEST(COALESCE(v_old_level,0), v_new_level);

  -- next threshold for xp progress
  SELECT threshold_coins INTO v_next_thresh
    FROM public.vip_level_config WHERE level = v_new_level + 1;

  UPDATE public.profiles
     SET vip_level      = v_new_level,
         vip_tier       = v_tier,
         vip_title      = v_title,
         vip_updated_at = now(),
         level          = v_new_level,
         xp             = CASE
                            WHEN v_next_thresh IS NULL THEN 0
                            ELSE GREATEST(0, LEAST(v_next_thresh - v_cur_thresh, v_new_total - v_cur_thresh))
                          END
   WHERE id = NEW.sender_id;

  IF v_new_level > COALESCE(v_old_level,0) THEN
    INSERT INTO public.vip_level_events(user_id, from_level, to_level, total_coins)
      VALUES (NEW.sender_id, COALESCE(v_old_level,0), v_new_level, v_new_total);

    INSERT INTO public.notifications(user_id, kind, title, body, data)
      VALUES (NEW.sender_id, 'system_broadcast',
              'VIP Level Up! ' || v_title,
              'You reached ' || v_tier || ' (Level ' || v_new_level || ').',
              jsonb_build_object('vip_level', v_new_level, 'tier', v_tier, 'title', v_title));
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tg_publish_milestone_broadcast(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_publish_milestone_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  hp record;
begin
  if (old.milestone_awarded_at is null) and (new.milestone_awarded_at is not null) then
    select username, avatar into hp from public.profiles where id = new.host_id;
    insert into public.milestone_broadcasts(room_id, host_id, host_username, host_avatar, room_title)
    values (new.id, new.host_id, hp.username, hp.avatar, new.title);
  end if;
  return new;
end;
$$;


--
-- Name: toggle_seat_lock(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_seat_lock(_room_id uuid, _seat_index integer, _locked boolean) RETURNS integer[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  r_host uuid;
  cur int[];
begin
  if me is null then raise exception 'not authenticated'; end if;

  select host_id, locked_seats into r_host, cur
    from public.live_rooms where id = _room_id;
  if r_host is null then raise exception 'room not found'; end if;

  if me <> r_host and not exists (
    select 1 from public.room_members
    where room_id = _room_id and user_id = me and is_moderator = true
  ) then
    raise exception 'only host or moderator can lock seats';
  end if;

  cur := coalesce(cur, '{}'::int[]);
  if _locked then
    if not (_seat_index = any(cur)) then
      cur := array_append(cur, _seat_index);
    end if;
  else
    cur := array_remove(cur, _seat_index);
  end if;

  update public.live_rooms set locked_seats = cur where id = _room_id;
  return cur;
end $$;


--
-- Name: touch_last_seen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_last_seen() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.profiles
     set last_seen = now()
   where id = auth.uid();
$$;


--
-- Name: trg_dm_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_dm_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    declare
      _row jsonb;
      _sender uuid;
      _recipient uuid;
      _kind text;
      _body text;
      _name text;
      _message_id text;
    begin
      _row := to_jsonb(NEW);
      _sender := nullif(_row ->> 'sender_id', '')::uuid;
      _recipient := nullif(coalesce(_row ->> 'recipient_id', _row ->> 'receiver_id'), '')::uuid;
      _kind := coalesce(nullif(_row ->> 'kind', ''), 'text');
      _message_id := _row ->> 'id';

      if _sender is null or _recipient is null or _sender = _recipient then
        return NEW;
      end if;

      _body := case _kind
        when 'image' then '📷 Photo'
        when 'video' then '🎬 Video'
        when 'voice' then '🎙️ Voice message'
        when 'album' then '🖼️ Shared from gallery'
        when 'file' then '📎 File'
        else left(coalesce(_row ->> 'message', _row ->> 'text', ''), 120)
      end;

      _name := public._notif_display_name(_sender);
      perform public.notify_user(
        _recipient,
        'dm_new',
        _name || ' sent you a message',
        nullif(_body, ''),
        jsonb_build_object('sender_id', _sender, 'message_id', _message_id),
        _sender,
        'dm',
        _message_id
      );

      return NEW;
    exception when others then
      -- Notifications must never break message sending.
      raise warning 'trg_dm_notify skipped: %', SQLERRM;
      return NEW;
    end $$;


--
-- Name: trg_follow_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_follow_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _name text;
begin
  if NEW.follower_id is null or NEW.following_id is null
     or NEW.follower_id = NEW.following_id then
    return NEW;
  end if;
  _name := public._notif_display_name(NEW.follower_id);
  perform public.notify_user(
    NEW.following_id,
    'friend_request',
    _name || ' started following you',
    null,
    jsonb_build_object('follower_id', NEW.follower_id),
    NEW.follower_id,
    'follow',
    NEW.follower_id::text
  );
  return NEW;
exception when others then
  raise warning 'trg_follow_notify skipped: %', SQLERRM;
  return NEW;
end $$;


--
-- Name: trg_friendship_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_friendship_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _name text;
begin
  if TG_OP = 'INSERT' and NEW.status = 'pending' then
    _name := public._notif_display_name(NEW.requester_id);
    perform public.notify_user(
      NEW.addressee_id, 'friend_request',
      _name || ' sent you a friend request',
      null,
      jsonb_build_object('requester_id', NEW.requester_id),
      NEW.requester_id, 'friendship', NEW.requester_id::text
    );
  elsif TG_OP = 'UPDATE' and NEW.status = 'accepted' and OLD.status <> 'accepted' then
    _name := public._notif_display_name(NEW.addressee_id);
    perform public.notify_user(
      NEW.requester_id, 'friend_accept',
      _name || ' accepted your friend request',
      null,
      jsonb_build_object('friend_id', NEW.addressee_id),
      NEW.addressee_id, 'friendship', NEW.addressee_id::text
    );
  end if;
  return NEW;
end $$;


--
-- Name: trg_guard_self_seat_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_guard_self_seat_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  is_host boolean;
  is_mod boolean;
  has_invite boolean;
  old_seat int;
begin
  -- Only care about the acting-as-self case.
  if me is null or NEW.user_id <> me then
    return NEW;
  end if;

  old_seat := case when TG_OP = 'UPDATE' then OLD.seat_index else null end;

  -- Leaving/clearing seat is always allowed.
  if NEW.seat_index is null then
    return NEW;
  end if;

  -- No change in seat_index on UPDATE → allow.
  if TG_OP = 'UPDATE' and old_seat is not distinct from NEW.seat_index then
    return NEW;
  end if;

  -- Host of the room is exempt.
  select (r.host_id = me) into is_host
    from public.live_rooms r where r.id = NEW.room_id;
  if coalesce(is_host, false) then return NEW; end if;

  -- Moderator of the room is exempt.
  select coalesce(m.is_moderator, false) into is_mod
    from public.room_members m
    where m.room_id = NEW.room_id and m.user_id = me;
  if coalesce(is_mod, false) then return NEW; end if;

  -- Must have an accepted invite for this room (matching seat or open seat).
  select exists(
    select 1 from public.seat_invites si
    where si.room_id = NEW.room_id
      and si.to_user = me
      and si.status = 'accepted'
      and (si.seat_index is null or si.seat_index = NEW.seat_index)
      and si.responded_at > now() - interval '30 seconds'
  ) into has_invite;

  if not has_invite then
    raise exception 'seat requires host or moderator invite'
      using errcode = '42501';
  end if;

  return NEW;
end $$;


--
-- Name: trg_live_room_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_live_room_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _host_name text;
  _title text;
  _became_live boolean := false;
begin
  if TG_OP = 'INSERT' and NEW.status = 'live' then
    _became_live := true;
  elsif TG_OP = 'UPDATE'
    and NEW.status = 'live'
    and (OLD.status is distinct from 'live') then
    _became_live := true;
  end if;

  if not _became_live then
    return NEW;
  end if;

  _host_name := public._notif_display_name(NEW.host_id);
  _title := _host_name || ' is live now';

  insert into public.notifications(user_id, kind, title, body, data, actor_id, entity_type, entity_id)
  select
    f.follower_id,
    'host_live'::public.notification_kind,
    _title,
    NEW.title,
    jsonb_build_object('room_id', NEW.id, 'host_id', NEW.host_id),
    NEW.host_id,
    'room',
    NEW.id::text
  from public.follows f
  where f.following_id = NEW.host_id
    and f.follower_id <> NEW.host_id
    and not exists (
      select 1 from public.notification_prefs np
      where np.user_id = f.follower_id
        and (np.in_app -> 'host_live')::boolean = false
    );

  return NEW;
exception when others then
  raise warning 'trg_live_room_notify skipped: %', SQLERRM;
  return NEW;
end $$;


--
-- Name: trg_recharge_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_recharge_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    begin
      if TG_OP = 'UPDATE' and NEW.status is distinct from OLD.status then
        if NEW.status = 'approved' then
          perform public.notify_user(
            NEW.user_id, 'recharge_approved',
            'Recharge approved',
            'Your recharge has been credited to your wallet.',
            jsonb_build_object('request_id', NEW.id, 'amount', NEW.amount),
            null, 'recharge', NEW.id::text
          );
        elsif NEW.status = 'rejected' then
          perform public.notify_user(
            NEW.user_id, 'recharge_rejected',
            'Recharge rejected',
            'Your recharge was not approved. Contact support if this is a mistake.',
            jsonb_build_object('request_id', NEW.id),
            null, 'recharge', NEW.id::text
          );
        end if;
      end if;
      return NEW;
    end $$;


