--

CREATE FUNCTION public.verify_room_pin(_room_id uuid, _pin text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.rooms
    WHERE id = _room_id AND (is_locked = false OR pin = _pin)
  );
$$;


--
-- Name: vip_period_start(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vip_period_start(p_period text) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(p_period)
    WHEN 'daily'   THEN date_trunc('day',   now())
    WHEN 'weekly'  THEN date_trunc('week',  now())
    WHEN 'monthly' THEN date_trunc('month', now())
    WHEN 'yearly'  THEN date_trunc('year',  now())
    ELSE 'epoch'::timestamptz
  END;
$$;


