    CONSTRAINT agora_slots_slot_index_check CHECK (((slot_index >= 1) AND (slot_index <= 20)))
);


--
-- Name: app_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_settings (
    id text DEFAULT 'global'::text NOT NULL,
    splash_enabled boolean DEFAULT true NOT NULL,
    splash_image text,
    splash_duration integer DEFAULT 5 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    coin_price_pkr numeric(10,4) DEFAULT 1.0 NOT NULL,
    diamond_price_pkr numeric(10,4) DEFAULT 0.5 NOT NULL,
    platform_diamonds bigint DEFAULT 0 NOT NULL,
    splash_video text,
    splash_video_poster text,
    custom_theme_price_coins integer DEFAULT 500 NOT NULL,
    custom_theme_duration_hours integer DEFAULT 24 NOT NULL,
    custom_theme_enabled boolean DEFAULT true NOT NULL,
    daily_spin_enabled boolean DEFAULT true NOT NULL,
